// Pacote <classviz>: os interativos das aulas de logística, LDA e QDA.
// Script clássico (sem import/export), sem dependências e sem rede. A matemática
// é a mesma de code/classificadores.py, reescrita em 2D.
//
//   <classviz mode="linear01"/>      regressão linear em {0,1} vs. logística (1D)
//   <classviz mode="sigmoid"/>       a sigmoide e a verossimilhança, com sliders
//   <classviz mode="bayes"/>         duas gaussianas e a fronteira de Bayes
//   <classviz mode="logistic-gd"/>   gradiente ascendente passo a passo
//   <classviz mode="qda"/>, "lda"    ajuste gaussiano vs. Bayes; methods="lda,qda" mostra os dois
//   <classviz mode="logistic"/>      logística ajustada vs. Bayes, nas mesmas gaussianas arrastáveis
//   <classviz mode="compare"/>       Bayes, logística, LDA e QDA nos três cenários
//   <classviz mode="draw"/>          o aluno desenha a partição; erro de treino e em dados novos
//   <classviz mode="mvn"/>           uma normal bivariada: média arrastável, σ₁, σ₂ e ρ nos sliders
//
// Atributos gerais: max-height (fração da altura da janela para o canvas, padrão 0.6).
(function () {
  "use strict";

  const T = (k, f) => (window.Delta && window.Delta.t ? window.Delta.t(k, f) : f);
  const pct = (v) => (100 * v).toFixed(1).replace(".", ",") + "%";
  const num = (v, d = 2) => v.toFixed(d).replace(".", ",").replace(/^-(0,0+)$/, "$1");

  // ---------------------------------------------------------------- aleatoriedade
  function mulberry32(a) {
    return function () {
      a = (a + 0x6d2b79f5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function randn(r) {
    let u = 0;
    while (u === 0) u = r();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r());
  }

  // ---------------------------------------------------------------- álgebra 2×2
  const det2 = (S) => S[0][0] * S[1][1] - S[0][1] * S[1][0];
  function chol2(S) {
    const l11 = Math.sqrt(S[0][0]);
    const l21 = S[1][0] / l11;
    return [l11, l21, Math.sqrt(Math.max(S[1][1] - l21 * l21, 1e-12))];
  }
  function maha(x, y, mu, S) {
    const dx = x - mu[0], dy = y - mu[1];
    return (S[1][1] * dx * dx - 2 * S[0][1] * dx * dy + S[0][0] * dy * dy) / det2(S);
  }
  const logN = (x, y, mu, S) => -Math.log(2 * Math.PI) - 0.5 * Math.log(det2(S)) - 0.5 * maha(x, y, mu, S);
  function lse(a) {
    let m = -Infinity;
    for (const v of a) if (v > m) m = v;
    let s = 0;
    for (const v of a) s += Math.exp(v - m);
    return m + Math.log(s);
  }
  const sig = (z) => (z >= 0 ? 1 / (1 + Math.exp(-z)) : Math.exp(z) / (1 + Math.exp(z)));
  const log1pexp = (z) => (z > 0 ? z + Math.log1p(Math.exp(-z)) : Math.log1p(Math.exp(z)));
  const cov = (s, r) => [[s * s, r * s * s], [r * s * s, s * s]];

  // ---------------------------------------------------------------- cenários
  // Os mesmos de CENARIOS em code/classificadores.py.
  const g = (w, mu, S) => ({ w, mu, S });
  const SCEN = {
    cov_iguais: { priors: [0.5, 0.5], classes: [
      [g(1, [-1, -0.5], [[1, 0.4], [0.4, 1]])],
      [g(1, [1, 0.7], [[1, 0.4], [0.4, 1]])] ] },
    cov_diferentes: { priors: [0.5, 0.5], classes: [
      [g(1, [-0.8, 0], [[0.8, 0.6], [0.6, 0.8]])],
      [g(1, [0.8, 0.3], [[2, -0.9], [-0.9, 1.2]])] ] },
    nao_gaussiano: { priors: [0.5, 0.5], classes: [
      [g(0.5, [-2, -1], [[0.5, 0], [0, 0.5]]), g(0.5, [2, -1], [[0.5, 0], [0, 0.5]])],
      [g(1, [0, 0.6], [[0.7, 0], [0, 0.5]])] ] },
  };
  const SCEN_LABEL = { cov_iguais: "Σ iguais", cov_diferentes: "Σ diferentes", nao_gaussiano: "não gaussiano" };

  const logDens = (sc, k, x, y) => lse(sc.classes[k].map((c) => Math.log(c.w) + logN(x, y, c.mu, c.S)));
  const bayesScore = (sc) => (x, y) =>
    Math.log(sc.priors[1]) + logDens(sc, 1, x, y) - Math.log(sc.priors[0]) - logDens(sc, 0, x, y);

  // Amostra "latente": sorteios fixos que viram pontos para qualquer valor dos
  // parâmetros. Arrastar uma média move a nuvem, em vez de sortear outra.
  function latent(n, seed) {
    const r = mulberry32(seed);
    return Array.from({ length: n }, () => ({ u: r(), v: r(), z1: randn(r), z2: randn(r) }));
  }
  function realize(sc, lat) {
    const X = [], y = [];
    for (const p of lat) {
      const k = p.u < sc.priors[1] ? 1 : 0;
      const comps = sc.classes[k];
      let acc = 0, c = comps[comps.length - 1];
      for (const cc of comps) { acc += cc.w; if (p.v < acc) { c = cc; break; } }
      const L = chol2(c.S);
      X.push([c.mu[0] + L[0] * p.z1, c.mu[1] + L[1] * p.z1 + L[2] * p.z2]);
      y.push(k);
    }
    return { X, y };
  }
  function testError(score, data) {
    let e = 0;
    for (let i = 0; i < data.X.length; i++) if ((score(data.X[i][0], data.X[i][1]) > 0 ? 1 : 0) !== data.y[i]) e++;
    return e / data.X.length;
  }

  // ---------------------------------------------------------------- modelos
  // Logística: X é uma lista de linhas (d atributos), beta tem d + 1 entradas.
  function logisticSteps(beta, X, y, lr, iters) {
    const n = X.length, d = beta.length;
    const grad = new Array(d);
    for (let it = 0; it < iters; it++) {
      grad.fill(0);
      for (let i = 0; i < n; i++) {
        let z = beta[0];
        for (let j = 1; j < d; j++) z += beta[j] * X[i][j - 1];
        const r = y[i] - sig(z);
        grad[0] += r;
        for (let j = 1; j < d; j++) grad[j] += r * X[i][j - 1];
      }
      for (let j = 0; j < d; j++) beta[j] += (lr * grad[j]) / n;
    }
    return Math.hypot(...grad) / n;
  }
  function loglik(beta, X, y) {
    let s = 0;
    for (let i = 0; i < X.length; i++) {
      let z = beta[0];
      for (let j = 1; j < beta.length; j++) z += beta[j] * X[i][j - 1];
      s += y[i] * z - log1pexp(z);
    }
    return s;
  }
  function fitLogistic(X, y) {
    const beta = new Array(X[0].length + 1).fill(0);
    logisticSteps(beta, X, y, 0.5, 3000);
    return beta;
  }
  const logisticScore = (b) => (x, y) => b[0] + b[1] * x + b[2] * y;

  function fitGaussian(X, y, shared) {
    const cnt = [0, 0], mean = [[0, 0], [0, 0]];
    for (let i = 0; i < X.length; i++) { cnt[y[i]]++; mean[y[i]][0] += X[i][0]; mean[y[i]][1] += X[i][1]; }
    if (cnt[0] < 3 || cnt[1] < 3) return null;
    for (const k of [0, 1]) { mean[k][0] /= cnt[k]; mean[k][1] /= cnt[k]; }
    const sums = [[[0, 0], [0, 0]], [[0, 0], [0, 0]]];
    for (let i = 0; i < X.length; i++) {
      const k = y[i], dx = X[i][0] - mean[k][0], dy = X[i][1] - mean[k][1], S = sums[k];
      S[0][0] += dx * dx; S[0][1] += dx * dy; S[1][1] += dy * dy;
    }
    for (const S of sums) S[1][0] = S[0][1];
    const scale = (S, c) => S.map((row) => row.map((v) => v / c));
    let covs = [scale(sums[0], cnt[0] - 1), scale(sums[1], cnt[1] - 1)];
    if (shared) {
      const P = scale(sums[0].map((row, i) => row.map((v, j) => v + sums[1][i][j])), X.length - 2);
      covs = [P, P];
    }
    return { priors: [cnt[0] / X.length, cnt[1] / X.length], means: mean, covs };
  }
  function gaussScore(m) {
    const d = (k, x, y) => -0.5 * Math.log(det2(m.covs[k])) - 0.5 * maha(x, y, m.means[k], m.covs[k]) + Math.log(m.priors[k]);
    return (x, y) => d(1, x, y) - d(0, x, y);
  }

  // ---------------------------------------------------------------- desenho
  // Os tokens do Delta são oklch(), color-mix() e relative colors, e a
  // propriedade crua pode ainda conter var(). Um elemento-sonda dentro do widget
  // deixa o navegador resolver tudo; background-color (não herdada) cai em
  // transparente quando o valor é inválido, e aí vale o fallback.
  function cssColor(el, name, fallback) {
    let probe = el.querySelector(":scope > .classviz-probe");
    if (!probe) {
      probe = document.createElement("span");
      probe.className = "classviz-probe";
      probe.hidden = true;
      el.append(probe);
    }
    probe.style.backgroundColor = `var(${name})`;
    const v = getComputedStyle(probe).backgroundColor;
    return v && v !== "rgba(0, 0, 0, 0)" && v !== "transparent" ? v : fallback;
  }
  const rgbCache = new Map();
  function toRGB(color) {
    if (rgbCache.has(color)) return rgbCache.get(color);
    const c = document.createElement("canvas");
    c.width = c.height = 1;
    const x = c.getContext("2d");
    x.fillStyle = color;
    x.fillRect(0, 0, 1, 1);
    const d = x.getImageData(0, 0, 1, 1).data;
    const rgb = [d[0], d[1], d[2]];
    rgbCache.set(color, rgb);
    return rgb;
  }

  class Plot {
    constructor(canvas, view, fonts) {
      this.fonts = fonts;
      this.canvas = canvas;
      this.ctx = canvas.getContext("2d");
      this.view = view;
      this.w = this.h = 1;
    }
    resize(w, h) {
      const dpr = window.devicePixelRatio || 1;
      this.w = w; this.h = h;
      this.canvas.width = Math.round(w * dpr);
      this.canvas.height = Math.round(h * dpr);
      this.canvas.style.width = w + "px";
      this.canvas.style.height = h + "px";
      this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }
    px(x) { const v = this.view; return ((x - v.x0) / (v.x1 - v.x0)) * this.w; }
    py(y) { const v = this.view; return this.h - ((y - v.y0) / (v.y1 - v.y0)) * this.h; }
    dx(px) { const v = this.view; return v.x0 + (px / this.w) * (v.x1 - v.x0); }
    dy(py) { const v = this.view; return v.y0 + ((this.h - py) / this.h) * (v.y1 - v.y0); }

    clear(paper) {
      const c = this.ctx;
      c.fillStyle = paper;
      c.fillRect(0, 0, this.w, this.h);
    }

    // Pinta P(Y = 1 | x) = σ(score): a cor da classe prevista, mais forte longe da fronteira.
    shade(score, c0, c1) {
      const cell = 5, nx = Math.ceil(this.w / cell), ny = Math.ceil(this.h / cell);
      const off = document.createElement("canvas");
      off.width = nx; off.height = ny;
      const oc = off.getContext("2d");
      const img = oc.createImageData(nx, ny);
      const a = toRGB(c0), b = toRGB(c1);
      for (let j = 0; j < ny; j++) {
        const y = this.dy((j + 0.5) * cell);
        for (let i = 0; i < nx; i++) {
          const p = sig(score(this.dx((i + 0.5) * cell), y));
          const col = p >= 0.5 ? b : a;
          const alpha = 0.65 * Math.pow(Math.abs(2 * p - 1), 0.8);
          const o = 4 * (j * nx + i);
          img.data[o] = col[0]; img.data[o + 1] = col[1]; img.data[o + 2] = col[2];
          img.data[o + 3] = Math.round(255 * alpha);
        }
      }
      oc.putImageData(img, 0, 0);
      const c = this.ctx;
      c.save();
      c.imageSmoothingEnabled = true;
      c.drawImage(off, 0, 0, nx * cell, ny * cell);
      c.restore();
    }

    // Pinta uma função com valores em [0, 1] (uma densidade normalizada pelo pico).
    heat(f, color) {
      const cell = 4, nx = Math.ceil(this.w / cell), ny = Math.ceil(this.h / cell);
      const off = document.createElement("canvas");
      off.width = nx; off.height = ny;
      const oc = off.getContext("2d");
      const img = oc.createImageData(nx, ny);
      const col = toRGB(color);
      for (let j = 0; j < ny; j++) {
        const y = this.dy((j + 0.5) * cell);
        for (let i = 0; i < nx; i++) {
          const o = 4 * (j * nx + i);
          img.data[o] = col[0]; img.data[o + 1] = col[1]; img.data[o + 2] = col[2];
          img.data[o + 3] = Math.round(255 * 0.75 * f(this.dx((i + 0.5) * cell), y));
        }
      }
      oc.putImageData(img, 0, 0);
      const c = this.ctx;
      c.save();
      c.imageSmoothingEnabled = true;
      c.drawImage(off, 0, 0, nx * cell, ny * cell);
      c.restore();
    }

    // A curva {score = 0} por marching squares, emendada em polilinhas (para o
    // tracejado não reiniciar a cada quadradinho).
    contour(score, style) {
      const step = 4, NX = Math.ceil(this.w / step), NY = Math.ceil(this.h / step);
      const V = new Float64Array((NX + 1) * (NY + 1));
      const at = (i, j) => V[j * (NX + 1) + i];
      for (let j = 0; j <= NY; j++)
        for (let i = 0; i <= NX; i++) V[j * (NX + 1) + i] = score(this.dx(i * step), this.dy(j * step));
      const pts = new Map();
      const edge = (i, j, vertical) => {
        const key = 2 * (j * (NX + 1) + i) + (vertical ? 1 : 0);
        if (!pts.has(key)) {
          const va = at(i, j), vb = vertical ? at(i, j + 1) : at(i + 1, j);
          const t = va / (va - vb);
          pts.set(key, vertical ? [i * step, (j + t) * step] : [(i + t) * step, j * step]);
        }
        return key;
      };
      const segs = [];
      for (let j = 0; j < NY; j++)
        for (let i = 0; i < NX; i++) {
          const a = at(i, j) > 0, b = at(i + 1, j) > 0, c = at(i + 1, j + 1) > 0, d = at(i, j + 1) > 0;
          const E = [];
          if (a !== b) E.push(edge(i, j, false));
          if (b !== c) E.push(edge(i + 1, j, true));
          if (d !== c) E.push(edge(i, j + 1, false));
          if (a !== d) E.push(edge(i, j, true));
          if (E.length === 2) segs.push(E);
          else if (E.length === 4) {
            const mid = (at(i, j) + at(i + 1, j) + at(i + 1, j + 1) + at(i, j + 1)) / 4 > 0;
            if (mid === a) segs.push([E[0], E[1]], [E[3], E[2]]);
            else segs.push([E[3], E[0]], [E[1], E[2]]);
          }
        }
      const byEdge = new Map();
      segs.forEach((s, idx) => s.forEach((e) => { if (!byEdge.has(e)) byEdge.set(e, []); byEdge.get(e).push(idx); }));
      const used = new Uint8Array(segs.length);
      const walk = (idx, from) => {
        const out = [];
        let cur = idx, e = from;
        while (true) {
          used[cur] = 1;
          const s = segs[cur], nextE = s[0] === e ? s[1] : s[0];
          out.push(nextE);
          const nb = (byEdge.get(nextE) || []).find((k) => !used[k]);
          if (nb === undefined) return out;
          cur = nb; e = nextE;
        }
      };
      const c = this.ctx;
      c.save();
      c.strokeStyle = style.color;
      c.lineWidth = style.width || 2.5;
      c.setLineDash(style.dash || []);
      c.lineJoin = c.lineCap = "round";
      for (let s = 0; s < segs.length; s++) {
        if (used[s]) continue;
        used[s] = 1;
        const fwd = walk(s, segs[s][0]);
        used[s] = 0;
        const back = walk(s, segs[s][1]);
        const line = back.reverse().concat(fwd).map((k) => pts.get(k));
        c.beginPath();
        line.forEach((p, k) => (k ? c.lineTo(p[0], p[1]) : c.moveTo(p[0], p[1])));
        c.stroke();
      }
      c.restore();
    }

    grid(ink, rule, labels) {
      const c = this.ctx, v = this.view;
      c.save();
      c.strokeStyle = rule;
      c.lineWidth = 1;
      c.globalAlpha = 0.45;
      c.beginPath();
      for (let x = Math.ceil(v.x0); x <= v.x1; x++) { c.moveTo(this.px(x), 0); c.lineTo(this.px(x), this.h); }
      for (let y = Math.ceil(v.y0); y <= v.y1; y++) { c.moveTo(0, this.py(y)); c.lineTo(this.w, this.py(y)); }
      c.stroke();
      c.globalAlpha = 1;
      if (labels) {
        c.fillStyle = ink;
        c.font = `italic 16px ${this.fonts.serif}`;
        c.textBaseline = "bottom";
        c.textAlign = "right";
        c.fillText(labels[0], this.w - 6, this.h - 4);
        c.textAlign = "left";
        c.textBaseline = "top";
        c.fillText(labels[1], 6, 4);
      }
      c.restore();
    }

    // Pontos cheios, na tinta escura da classe e sem contorno.
    points(X, y, cols, yOf) {
      const c = this.ctx;
      c.save();
      for (let i = 0; i < X.length; i++) {
        const px = this.px(X[i][0]), py = this.py(yOf ? yOf(i) : X[i][1]);
        c.fillStyle = cols[y[i]];
        c.beginPath();
        if (y[i] === 1) c.rect(px - 3.6, py - 3.6, 7.2, 7.2);
        else c.arc(px, py, 4, 0, 2 * Math.PI);
        c.fill();
      }
      c.restore();
    }

    ellipse(mu, S, r, color, width, dash) {
      const a = S[0][0], b = S[0][1], d = S[1][1];
      const tr = (a + d) / 2, disc = Math.sqrt(((a - d) / 2) ** 2 + b * b);
      const l1 = tr + disc, l2 = Math.max(tr - disc, 1e-9);
      const ang = Math.atan2(l1 - a, b || 1e-12);
      const c = this.ctx;
      c.save();
      c.strokeStyle = color;
      c.lineWidth = width || 1.5;
      c.setLineDash(dash || []);
      c.beginPath();
      for (let k = 0; k <= 64; k++) {
        const t = (2 * Math.PI * k) / 64;
        const u = r * Math.sqrt(l1) * Math.cos(t), w = r * Math.sqrt(l2) * Math.sin(t);
        const x = mu[0] + u * Math.cos(ang) - w * Math.sin(ang);
        const y = mu[1] + u * Math.sin(ang) + w * Math.cos(ang);
        k ? this.ctx.lineTo(this.px(x), this.py(y)) : this.ctx.moveTo(this.px(x), this.py(y));
      }
      c.stroke();
      c.restore();
    }

    handle(mu, label, fill, ink) {
      const c = this.ctx, x = this.px(mu[0]), y = this.py(mu[1]);
      c.save();
      c.fillStyle = fill;
      c.strokeStyle = ink;
      c.lineWidth = 2.5;
      c.beginPath();
      c.arc(x, y, 9, 0, 2 * Math.PI);
      c.fill();
      c.stroke();
      c.fillStyle = ink;
      c.font = `600 16px ${this.fonts.sans}`;
      c.textBaseline = "bottom";
      c.textAlign = "left";
      c.fillText(label, x + 11, y - 7);
      c.restore();
    }

    curve(f, color, width, dash) {
      const c = this.ctx;
      c.save();
      c.strokeStyle = color;
      c.lineWidth = width || 2.5;
      c.setLineDash(dash || []);
      c.lineJoin = c.lineCap = "round";
      c.beginPath();
      for (let px = 0; px <= this.w; px += 2) {
        const y = this.py(f(this.dx(px)));
        px ? c.lineTo(px, y) : c.moveTo(px, y);
      }
      c.stroke();
      c.restore();
    }

    vline(x, color, dash) {
      const c = this.ctx;
      c.save();
      c.strokeStyle = color;
      c.lineWidth = 1.5;
      c.setLineDash(dash || [3, 4]);
      c.beginPath();
      c.moveTo(this.px(x), 0);
      c.lineTo(this.px(x), this.h);
      c.stroke();
      c.restore();
    }

    hline(y, color, dash, width) {
      const c = this.ctx;
      c.save();
      c.strokeStyle = color;
      c.lineWidth = width || 1;
      c.setLineDash(dash || []);
      c.beginPath();
      c.moveTo(0, this.py(y));
      c.lineTo(this.w, this.py(y));
      c.stroke();
      c.restore();
    }

    text(s, x, y, color, align, font) {
      const c = this.ctx;
      c.save();
      c.fillStyle = color;
      c.font = `${font || "14px"} ${this.fonts.sans}`;
      c.textAlign = align || "left";
      c.textBaseline = "middle";
      c.fillText(s, this.px(x), this.py(y));
      c.restore();
    }

    xticks(ink, from, to) {
      const c = this.ctx;
      c.save();
      c.fillStyle = ink;
      c.font = `13px ${this.fonts.sans}`;
      c.textAlign = "center";
      c.textBaseline = "bottom";
      for (let x = from; x <= to; x++) c.fillText(String(x).replace("-", "−"), this.px(x), this.h - 4);
      c.restore();
    }
  }

  // ---------------------------------------------------------------- interface
  function buildUI(el, aspect) {
    el.textContent = "";
    const fig = document.createElement("div");
    fig.className = "classviz-fig";
    const canvas = document.createElement("canvas");
    canvas.className = "classviz-canvas";
    fig.append(canvas);
    const panel = document.createElement("div");
    panel.className = "classviz-panel";
    el.append(fig, panel);

    const ui = { canvas, panel, fig, aspect };
    ui.group = (title) => {
      const box = document.createElement("div");
      box.className = "classviz-group";
      if (title) {
        const h = document.createElement("div");
        h.className = "classviz-group-title";
        h.textContent = title;
        box.append(h);
      }
      panel.append(box);
      return box;
    };
    ui.slider = (parent, label, o, onInput) => {
      const row = document.createElement("label");
      row.className = "classviz-row";
      const lab = document.createElement("span");
      lab.className = "classviz-label";
      lab.textContent = label;
      const inp = document.createElement("input");
      inp.type = "range";
      inp.className = "range classviz-range";
      inp.min = o.min; inp.max = o.max; inp.step = o.step; inp.value = o.value;
      const out = document.createElement("output");
      out.className = "classviz-value";
      const fmt = o.fmt || ((v) => num(v));
      const sync = () => (out.textContent = fmt(Number(inp.value)));
      sync();
      inp.addEventListener("input", () => { sync(); onInput(Number(inp.value)); });
      row.append(lab, inp, out);
      parent.append(row);
      return { input: inp, set(v) { inp.value = v; sync(); }, row };
    };
    ui.button = (parent, label, onClick, primary) => {
      const b = document.createElement("button");
      b.type = "button";
      b.className = "btn classviz-btn" + (primary ? " primary" : "");
      b.textContent = label;
      b.addEventListener("click", onClick);
      parent.append(b);
      return b;
    };
    ui.buttons = (parent) => {
      const row = document.createElement("div");
      row.className = "classviz-buttons";
      parent.append(row);
      return row;
    };
    ui.check = (parent, label, value, onChange, swatch) => {
      const row = document.createElement("label");
      row.className = "classviz-check";
      const inp = document.createElement("input");
      inp.type = "checkbox";
      inp.checked = value;
      inp.addEventListener("change", () => onChange(inp.checked));
      row.append(inp);
      if (swatch) row.append(makeSwatch(swatch));
      row.append(document.createTextNode(label));
      parent.append(row);
      return inp;
    };
    ui.readout = (parent) => {
      const d = document.createElement("div");
      d.className = "classviz-readout";
      parent.append(d);
      return d;
    };
    ui.legend = (parent, items) => {
      const d = document.createElement("div");
      d.className = "classviz-legend";
      for (const it of items) {
        const r = document.createElement("div");
        r.className = "classviz-legend-item";
        r.append(makeSwatch(it), document.createTextNode(it.label));
        d.append(r);
      }
      parent.append(d);
      return d;
    };
    return ui;
  }

  function makeSwatch(it) {
    const s = document.createElement("span");
    s.className = "classviz-swatch classviz-swatch-" + (it.kind || "line");
    s.style.setProperty("--sw", it.color);
    if (it.dash) s.classList.add("is-dashed");
    return s;
  }

  // ---------------------------------------------------------------- o elemento
  // Registrado no fim do script: define() já promove os <delta-classviz> da
  // página, e MODES precisa existir quando isso acontece.
  const register = () => customElements.define(
    "delta-classviz",
    class extends HTMLElement {
      connectedCallback() {
        if (this.dataset.deltaReady) return;
        this.dataset.deltaReady = "1";

        // O deck troca de slide com setas, espaço e swipe. Dentro do widget, não.
        for (const ev of ["touchstart", "touchend"]) this.addEventListener(ev, (e) => e.stopPropagation());
        this.addEventListener("keydown", (e) => {
          if ((e.key === " " || e.key === "Enter") && e.target.tagName === "BUTTON") e.stopPropagation();
        });

        const mode = this.getAttribute("mode") || "bayes";
        const setup = MODES[mode];
        if (!setup) { this.textContent = `classviz: modo desconhecido "${mode}"`; return; }
        this.classList.add("classviz-" + mode);
        const is1D = mode === "linear01" || mode === "sigmoid";
        const ui = buildUI(this, is1D ? 2 : 1.5);
        const view = is1D ? null : { x0: -4.5, x1: 4.5, y0: -3, y1: 3 };
        const cs = getComputedStyle(this);
        const fonts = {
          sans: cs.getPropertyValue("--delta-sans").trim() || "system-ui, sans-serif",
          serif: cs.getPropertyValue("--delta-serif").trim() || "serif",
        };
        const plot = new Plot(ui.canvas, view, fonts);
        const colors = () => ({
          paper: cssColor(this, "--classviz-paper", "#fff"),
          ink: cssColor(this, "--classviz-ink", "#121212"),
          rule: cssColor(this, "--classviz-rule", "#d0d0d0"),
          mute: cssColor(this, "--classviz-mute", "#777"),
          c0: cssColor(this, "--classviz-c0", "#ffc555"),
          c1: cssColor(this, "--classviz-c1", "#ff8aef"),
          p0: cssColor(this, "--classviz-p0", "#b07a00"),
          p1: cssColor(this, "--classviz-p1", "#c040b0"),
          log: cssColor(this, "--classviz-log", "#2f6fdf"),
          lda: cssColor(this, "--classviz-lda", "#129a5f"),
          qda: cssColor(this, "--classviz-qda", "#8a3ffc"),
        });

        let pending = false, draw = () => {};
        const redraw = () => {
          if (pending) return;
          pending = true;
          requestAnimationFrame(() => { pending = false; if (plot.w > 1) draw(colors()); });
        };
        const api = { el: this, ui, plot, redraw, setDraw: (f) => (draw = f), colors };
        setup(api);

        const fit = () => {
          const avail = ui.fig.clientWidth;
          if (!avail) return;
          const frac = parseFloat(this.getAttribute("max-height")) || 0.6;
          const maxH = Math.max(220, window.innerHeight * frac);
          let w = avail, h = w / ui.aspect;
          if (h > maxH) { h = maxH; w = h * ui.aspect; }
          plot.resize(Math.floor(w), Math.floor(h));
          draw(colors());
        };
        new ResizeObserver(fit).observe(ui.fig);

        // Acento e modo do documento podem mudar depois do desenho (tema "auto",
        // troca de data-accent/data-mode); o canvas não acompanha sozinho.
        new MutationObserver(redraw).observe(document.documentElement, {
          attributes: true, subtree: true, attributeFilter: ["data-accent", "data-mode"],
        });
        matchMedia("(prefers-color-scheme: dark)").addEventListener("change", redraw);
      }
    },
  );

  // Arrastar as médias verdadeiras.
  function draggable(api, handles, onMove) {
    const { plot, ui } = api;
    let active = null;
    const hit = (e) => {
      const r = ui.canvas.getBoundingClientRect();
      const x = e.clientX - r.left, y = e.clientY - r.top;
      let best = null, bd = 18;
      handles().forEach((mu, i) => {
        const d = Math.hypot(plot.px(mu[0]) - x, plot.py(mu[1]) - y);
        if (d < bd) { bd = d; best = i; }
      });
      return { best, x, y };
    };
    ui.canvas.addEventListener("pointerdown", (e) => {
      const h = hit(e);
      if (h.best === null) return;
      active = h.best;
      ui.canvas.setPointerCapture(e.pointerId);
      ui.canvas.classList.add("is-dragging");
      e.preventDefault();
    });
    ui.canvas.addEventListener("pointermove", (e) => {
      const h = hit(e);
      if (active === null) {
        ui.canvas.classList.toggle("is-grabbable", h.best !== null);
        return;
      }
      const v = plot.view;
      const x = Math.min(v.x1 - 0.3, Math.max(v.x0 + 0.3, plot.dx(h.x)));
      const y = Math.min(v.y1 - 0.3, Math.max(v.y0 + 0.3, plot.dy(h.y)));
      onMove(active, [x, y]);
    });
    const end = () => { active = null; ui.canvas.classList.remove("is-dragging"); };
    ui.canvas.addEventListener("pointerup", end);
    ui.canvas.addEventListener("pointercancel", end);
  }

  // Duas gaussianas parametrizadas pelos controles.
  function twoGaussians(p) {
    const S0 = cov(1, p.rho0);
    const S1 = p.equal ? S0 : cov(p.s1, p.rho1);
    return { priors: [1 - p.pi1, p.pi1], classes: [[g(1, p.mu0, S0)], [g(1, p.mu1, S1)]] };
  }
  function gaussianControls(api, p, box, opts) {
    const { ui, redraw } = api;
    const sliders = {};
    const refreshEq = () => {
      for (const k of ["rho1", "s1"]) {
        sliders[k].input.disabled = p.equal;
        sliders[k].row.classList.toggle("is-disabled", p.equal);
      }
    };
    ui.check(box, "Σ₀ = Σ₁", p.equal, (v) => { p.equal = v; refreshEq(); redraw(); });
    sliders.rho0 = ui.slider(box, "ρ₀", { min: -0.9, max: 0.9, step: 0.05, value: p.rho0 }, (v) => { p.rho0 = v; redraw(); });
    sliders.rho1 = ui.slider(box, "ρ₁", { min: -0.9, max: 0.9, step: 0.05, value: p.rho1 }, (v) => { p.rho1 = v; redraw(); });
    sliders.s1 = ui.slider(box, "σ₁", { min: 0.5, max: 2, step: 0.05, value: p.s1 }, (v) => { p.s1 = v; redraw(); });
    if (opts && opts.prior)
      ui.slider(box, "π₁", { min: 0.2, max: 0.8, step: 0.05, value: p.pi1 }, (v) => { p.pi1 = v; redraw(); });
    refreshEq();
    draggable(api, () => [p.mu0, p.mu1], (i, mu) => { p[i ? "mu1" : "mu0"] = mu; redraw(); });
  }

  // Dados 1D das duas primeiras figuras.
  function data1D(seed, extra) {
    const r = mulberry32(seed), X = [], y = [];
    for (let i = 0; i < 25; i++) { X.push([-1 + 0.9 * randn(r)]); y.push(0); }
    for (let i = 0; i < 25; i++) { X.push([1.3 + 0.9 * randn(r)]); y.push(1); }
    for (let i = 0; i < extra; i++) { X.push([8 + 0.6 * randn(r)]); y.push(1); }
    return { X, y, jitter: X.map(() => (r() - 0.5) * 0.08) };
  }

  // Um botão que abre um balão explicativo (Delta.popover, o mesmo das referências).
  const LL_HELP = `
    <div class="classviz-pop-title">O que é ℓ(β)?</div>
    <p>Para cada ponto, o modelo diz com que probabilidade ele seria da classe que de fato tem:
    p(xᵢ) se yᵢ = 1, e 1 − p(xᵢ) se yᵢ = 0. A log-verossimilhança ℓ(β) soma os logs dessas
    probabilidades.</p>
    <p>Como são logs de probabilidades, ℓ ≤ 0. Quanto mais perto de zero, mais plausíveis são os
    dados que observamos sob esse β.</p>
    <p>Um ponto do lado errado com previsão confiante custa caro: se o modelo dá p ≈ 0,01 a quem é
    da classe 1, paga log 0,01 ≈ −4,6 por esse ponto sozinho.</p>
    <p>A estimativa de <b>máxima verossimilhança</b> é o β que deixa ℓ o maior possível. Procure-o
    nos sliders; o botão acha por você.</p>`;

  function helpPopover(ui, label, html) {
    const row = ui.buttons(ui.panel);
    const trigger = document.createElement("button");
    trigger.type = "button";
    trigger.className = "btn classviz-btn classviz-help";
    trigger.textContent = label;
    row.append(trigger);
    const content = document.createElement("div");
    content.className = "classviz-pop";
    content.innerHTML = html;
    if (window.Delta && window.Delta.popover) window.Delta.popover(trigger, content);
  }

  // Ponto dentro de polígono (ray casting). O polígono é uma lista de [x, y].
  function inside(poly, x, y) {
    let c = false;
    for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      const [xi, yi] = poly[i], [xj, yj] = poly[j];
      if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) c = !c;
    }
    return c;
  }

  const MODES = {
    // ------------------------------------------------------------ draw
    // Um classificador é uma partição do plano: o aluno a desenha à mão.
    draw(api) {
      const { el, ui, plot, redraw, setDraw } = api;
      const sc = SCEN[el.getAttribute("scenario") || "cov_diferentes"] || SCEN.cov_diferentes;
      const d = realize(sc, latent(100, 31)), T_ = realize(sc, latent(4000, 777));
      const st = { polys: [], cur: null, invert: false, tested: false, bayes: false };
      const cls = (x, y) => {
        const k = st.polys.some((p) => inside(p, x, y)) ? 1 : 0;
        return st.invert ? 1 - k : k;
      };
      const errOn = (data) => {
        let e = 0;
        for (let i = 0; i < data.X.length; i++) if (cls(data.X[i][0], data.X[i][1]) !== data.y[i]) e++;
        return e;
      };

      const box = ui.group(T("classviz.yours", "Seu classificador"));
      const row = ui.buttons(box);
      ui.button(row, "apagar", () => { st.polys = []; st.tested = false; redraw(); });
      ui.button(row, "inverter", () => { st.invert = !st.invert; st.tested = false; redraw(); });
      const out = ui.readout(box);
      const box2 = ui.group(T("classviz.eval", "E em dados novos?"));
      ui.button(ui.buttons(box2), "avaliar em dados novos", () => { st.tested = true; redraw(); }, true);
      const out2 = ui.readout(box2);
      const c = api.colors();
      ui.check(box2, "fronteira de Bayes", st.bayes, (v) => { st.bayes = v; redraw(); }, { color: c.ink, dash: true });

      const toData = (e) => {
        const r = ui.canvas.getBoundingClientRect();
        return [plot.dx(e.clientX - r.left), plot.dy(e.clientY - r.top)];
      };
      ui.canvas.classList.add("is-drawable");
      ui.canvas.addEventListener("pointerdown", (e) => {
        st.cur = [toData(e)];
        ui.canvas.setPointerCapture(e.pointerId);
        e.preventDefault();
      });
      ui.canvas.addEventListener("pointermove", (e) => {
        if (!st.cur) return;
        const q = toData(e), last = st.cur[st.cur.length - 1];
        if (Math.hypot(plot.px(q[0]) - plot.px(last[0]), plot.py(q[1]) - plot.py(last[1])) < 3) return;
        st.cur.push(q);
        redraw();
      });
      const end = () => {
        if (!st.cur) return;
        if (st.cur.length >= 3) { st.polys.push(st.cur); st.tested = false; }
        st.cur = null;
        redraw();
      };
      ui.canvas.addEventListener("pointerup", end);
      ui.canvas.addEventListener("pointercancel", end);

      setDraw((c) => {
        const ctx = plot.ctx;
        plot.clear(c.paper);
        if (st.polys.length || st.invert) plot.shade((x, y) => (cls(x, y) ? 4 : -4), c.c0, c.c1);
        plot.grid(c.ink, c.rule, ["x₁", "x₂"]);
        if (st.bayes) plot.contour(bayesScore(sc), { color: c.ink, width: 2.5, dash: [7, 5] });
        // as curvas desenhadas (e a que está sendo desenhada)
        ctx.save();
        ctx.strokeStyle = c.ink;
        ctx.lineWidth = 2.5;
        ctx.lineJoin = ctx.lineCap = "round";
        for (const poly of st.polys.concat(st.cur ? [st.cur] : [])) {
          ctx.beginPath();
          poly.forEach(([x, y], k) => (k ? ctx.lineTo(plot.px(x), plot.py(y)) : ctx.moveTo(plot.px(x), plot.py(y))));
          if (poly !== st.cur) ctx.closePath();
          ctx.stroke();
        }
        ctx.restore();
        if (st.tested) {
          // uma parte dos dados novos, pequena e translúcida
          ctx.save();
          ctx.globalAlpha = 0.55;
          const cols = [c.p0, c.p1];
          for (let i = 0; i < 700; i++) {
            ctx.fillStyle = cols[T_.y[i]];
            ctx.beginPath();
            ctx.arc(plot.px(T_.X[i][0]), plot.py(T_.X[i][1]), 2.2, 0, 2 * Math.PI);
            ctx.fill();
          }
          ctx.restore();
        }
        plot.points(d.X, d.y, [c.p0, c.p1]);
        if (!st.polys.length && !st.cur && !st.invert)
          plot.text("arraste para desenhar uma região: dentro dela, classe ■", 0, 2.7, c.ink, "center", "600 15px");
        const e = errOn(d);
        out.innerHTML = `<div>erro de treino: <b>${pct(e / d.X.length)}</b> (${e} de ${d.X.length})</div>`;
        let html = st.tested
          ? `<div>erro em dados novos: <b>${pct(errOn(T_) / T_.X.length)}</b></div>`
          : `<div class="classviz-note">Desenhe primeiro. Depois veja como a sua partição se sai em 4000 pontos que ela nunca viu.</div>`;
        if (st.bayes) html += `<div>risco de Bayes ≈ <b>${pct(testError(bayesScore(sc), T_))}</b></div>`;
        out2.innerHTML = html;
      });
    },


    // ------------------------------------------------------------ linear01
    linear01(api) {
      const { ui, plot, redraw, setDraw } = api;
      plot.view = { x0: -4, x1: 10, y0: -0.55, y1: 1.45 };
      const logMode = api.el.getAttribute("logistic") || "toggle";
      const st = { extra: false, logistic: logMode === "shown" };
      const box = ui.group(T("classviz.data", "Dados"));
      ui.check(box, "10 pontos da classe 1 em x ≈ 8", st.extra, (v) => { st.extra = v; redraw(); });
      if (logMode === "toggle") ui.check(box, "mostrar a logística", st.logistic, (v) => { st.logistic = v; redraw(); });
      const out = ui.readout(ui.group(T("classviz.threshold", "Onde se decide (ŷ = 1/2)")));
      const c = api.colors();
      ui.legend(ui.panel, [{ label: "mínimos quadrados", color: c.ink }]
        .concat(logMode === "hidden" ? [] : [{ label: "logística", color: c.log }]));
      setDraw((c) => {
        const d = data1D(3, st.extra ? 10 : 0);
        const n = d.X.length;
        const mx = d.X.reduce((s, v) => s + v[0], 0) / n, my = d.y.reduce((s, v) => s + v, 0) / n;
        let sxy = 0, sxx = 0;
        for (let i = 0; i < n; i++) { sxy += (d.X[i][0] - mx) * (d.y[i] - my); sxx += (d.X[i][0] - mx) ** 2; }
        const b1 = sxy / sxx, b0 = my - b1 * mx, tLS = (0.5 - b0) / b1;
        const beta = fitLogistic(d.X, d.y), tLog = -beta[0] / beta[1];
        const errLS = d.X.reduce((e, x, i) => e + ((b0 + b1 * x[0] >= 0.5 ? 1 : 0) !== d.y[i]), 0) / n;
        const errLog = d.X.reduce((e, x, i) => e + ((beta[0] + beta[1] * x[0] >= 0 ? 1 : 0) !== d.y[i]), 0) / n;

        plot.clear(c.paper);
        const ctx = plot.ctx;
        ctx.save();
        ctx.fillStyle = c.rule;
        ctx.globalAlpha = 0.35;
        ctx.fillRect(0, 0, plot.w, plot.py(1));
        ctx.fillRect(0, plot.py(0), plot.w, plot.h - plot.py(0));
        ctx.restore();
        plot.text("probabilidade > 1 ?!", plot.view.x0 + 0.15, 1.3, c.mute);
        plot.text("probabilidade < 0 ?!", plot.view.x0 + 0.15, -0.4, c.mute);
        plot.hline(0, c.mute, [4, 4]);
        plot.hline(1, c.mute, [4, 4]);
        plot.hline(0.5, c.rule, [2, 5]);
        plot.text("y = 1", plot.view.x1 - 0.1, 1.06, c.mute, "right");
        plot.text("y = 0", plot.view.x1 - 0.1, -0.06, c.mute, "right");
        plot.xticks(c.mute, -3, 9);
        plot.curve((x) => b0 + b1 * x, c.ink, 2.5);
        plot.vline(tLS, c.ink);
        if (st.logistic) {
          plot.curve((x) => sig(beta[0] + beta[1] * x), c.log, 2.5);
          plot.vline(tLog, c.log);
        }
        plot.points(d.X, d.y, [c.p0, c.p1], (i) => d.y[i] + d.jitter[i]);
        out.innerHTML =
          `<div>mínimos quadrados: <b>x = ${num(tLS)}</b> · erro ${pct(errLS)}</div>` +
          (st.logistic ? `<div>logística: <b>x = ${num(tLog)}</b> · erro ${pct(errLog)}</div>` : "");
      });
    },

    // ------------------------------------------------------------ sigmoid
    sigmoid(api) {
      const { ui, plot, redraw, setDraw } = api;
      plot.view = { x0: -6, x1: 6, y0: -0.12, y1: 1.12 };
      const d = data1D(11, 0);
      const st = { b0: 0, b1: 1 };
      const box = ui.group(T("classviz.params", "Parâmetros"));
      const s0 = ui.slider(box, "β₀", { min: -6, max: 6, step: 0.1, value: st.b0, fmt: (v) => num(v, 1) }, (v) => { st.b0 = v; redraw(); });
      const s1 = ui.slider(box, "β₁", { min: -4, max: 6, step: 0.1, value: st.b1, fmt: (v) => num(v, 1) }, (v) => { st.b1 = v; redraw(); });
      const row = ui.buttons(box);
      ui.button(row, "máxima verossimilhança", () => {
        const b = fitLogistic(d.X, d.y);
        st.b0 = Math.round(b[0] * 10) / 10; st.b1 = Math.round(b[1] * 10) / 10;
        s0.set(st.b0); s1.set(st.b1); redraw();
      }, true);
      const out = ui.readout(ui.group());
      helpPopover(ui, "O que é ℓ(β)?", LL_HELP);
      setDraw((c) => {
        const b = [st.b0, st.b1];
        const ll = loglik(b, d.X, d.y);
        plot.clear(c.paper);
        plot.hline(0, c.mute, [4, 4]);
        plot.hline(1, c.mute, [4, 4]);
        plot.hline(0.5, c.rule, [2, 5]);
        plot.xticks(c.mute, -5, 5);
        if (Math.abs(st.b1) > 1e-9) plot.vline(-st.b0 / st.b1, c.log);
        plot.curve((x) => sig(st.b0 + st.b1 * x), c.log, 3);
        plot.points(d.X, d.y, [c.p0, c.p1], (i) => d.y[i] + d.jitter[i]);
        const fr = Math.abs(st.b1) > 1e-9 ? num(-st.b0 / st.b1) : "—";
        out.innerHTML =
          `<div>fronteira: <b>x = −β₀/β₁ = ${fr}</b></div>` +
          `<div>log-verossimilhança: <b>ℓ(β) = ${num(ll, 1)}</b></div>`;
      });
    },

    // ------------------------------------------------------------ bayes
    bayes(api) {
      const { ui, plot, redraw, setDraw } = api;
      const p = { mu0: [-1, -0.5], mu1: [1, 0.7], rho0: 0.4, rho1: -0.5, s1: 1.3, pi1: 0.5, equal: true };
      const lat = latent(200, 5), test = latent(4000, 99);
      gaussianControls(api, p, ui.group(T("classviz.truth", "A distribuição verdadeira")), { prior: true });
      const out = ui.readout(ui.group());
      const c = api.colors();
      ui.legend(ui.panel, [
        { label: "fronteira de Bayes", color: c.ink },
        { label: "P(Y = 1 | x): cor e intensidade", kind: "fill", color: c.c1 },
      ]);
      setDraw((c) => {
        const sc = twoGaussians(p), score = bayesScore(sc), d = realize(sc, lat);
        plot.clear(c.paper);
        plot.shade(score, c.c0, c.c1);
        plot.grid(c.ink, c.rule, ["x₁", "x₂"]);
        for (const r of [1, 2]) {
          plot.ellipse(sc.classes[0][0].mu, sc.classes[0][0].S, r, c.ink, 1, [2, 3]);
          plot.ellipse(sc.classes[1][0].mu, sc.classes[1][0].S, r, c.ink, 1, [2, 3]);
        }
        plot.contour(score, { color: c.ink, width: 3 });
        plot.points(d.X, d.y, [c.p0, c.p1]);
        plot.handle(p.mu0, "μ₀", c.c0, c.p0);
        plot.handle(p.mu1, "μ₁", c.c1, c.p1);
        out.innerHTML =
          `<div>risco de Bayes ≈ <b>${pct(testError(score, realize(sc, test)))}</b></div>` +
          `<div class="classviz-note">Arraste μ₀ e μ₁ para mover as classes.</div>`;
      });
    },

    // ------------------------------------------------------------ logistic-gd
    "logistic-gd"(api) {
      const { el, ui, plot, redraw, setDraw } = api;
      const key = el.getAttribute("scenario") || "cov_iguais";
      const sc = SCEN[key] || SCEN.cov_iguais;
      const d = realize(sc, latent(120, 21));
      const st = { beta: [0, 0, 0], t: 0, lr: 0.5, hist: [loglik([0, 0, 0], d.X, d.y) / d.X.length], running: false, bayes: false, g: Infinity };
      const box = ui.group(T("classviz.gd", "Gradiente ascendente"));
      const row = ui.buttons(box);
      const step = (k) => {
        for (let i = 0; i < k; i++) {
          st.g = logisticSteps(st.beta, d.X, d.y, st.lr, 1);
          st.t++;
          st.hist.push(loglik(st.beta, d.X, d.y) / d.X.length);
        }
        redraw();
      };
      ui.button(row, "1 passo", () => step(1));
      ui.button(row, "+50", () => step(50));
      const run = ui.button(row, "▶ rodar", () => {
        st.running = !st.running;
        run.textContent = st.running ? "❚❚ pausar" : "▶ rodar";
        if (st.running) loop();
      }, true);
      ui.button(row, "reiniciar", () => {
        st.beta = [0, 0, 0]; st.t = 0; st.g = Infinity;
        st.hist = [loglik(st.beta, d.X, d.y) / d.X.length];
        redraw();
      });
      const loop = () => {
        if (!st.running) return;
        step(3);
        if (st.g < 1e-5 || !el.isConnected) {
          st.running = false;
          run.textContent = "▶ rodar";
          return;
        }
        requestAnimationFrame(loop);
      };
      ui.slider(box, "taxa", { min: 0.5, max: 40, step: 0.5, value: st.lr, fmt: (v) => num(v, 1) }, (v) => (st.lr = v));
      ui.check(box, "fronteira de Bayes", st.bayes, (v) => { st.bayes = v; redraw(); });
      const out = ui.readout(ui.group());
      const spark = document.createElement("canvas");
      spark.className = "classviz-spark";
      ui.panel.append(spark);

      setDraw((c) => {
        const score = logisticScore(st.beta);
        plot.clear(c.paper);
        plot.shade(score, c.c0, c.c1);
        plot.grid(c.ink, c.rule, ["x₁", "x₂"]);
        if (st.bayes) plot.contour(bayesScore(sc), { color: c.ink, width: 2, dash: [7, 5] });
        plot.contour(score, { color: c.log, width: 3 });
        plot.points(d.X, d.y, [c.p0, c.p1]);
        const b = st.beta;
        out.innerHTML =
          `<div>iteração <b>${st.t}</b></div>` +
          `<div>β = (${num(b[0])}; ${num(b[1])}; ${num(b[2])})</div>` +
          `<div>ℓ(β)/n = <b>${num(st.hist[st.hist.length - 1], 4)}</b></div>` +
          `<div>erro de treino: ${pct(testError(score, d))}</div>`;
        drawSpark(spark, st.hist, c);
      });
    },

    // ------------------------------------------------------------ mvn
    // Uma única normal bivariada: a densidade, as elipses de nível e uma amostra.
    mvn(api) {
      const { ui, plot, redraw, setDraw } = api;
      const p = { mu: [0, 0], s1: 1, s2: 1, rho: 0.5 };
      const st = { sample: true, ellipses: true };
      const lat = latent(300, 13);
      const box = ui.group(T("classviz.params", "Parâmetros"));
      ui.slider(box, "σ₁", { min: 0.3, max: 2, step: 0.05, value: p.s1 }, (v) => { p.s1 = v; redraw(); });
      ui.slider(box, "σ₂", { min: 0.3, max: 2, step: 0.05, value: p.s2 }, (v) => { p.s2 = v; redraw(); });
      ui.slider(box, "ρ", { min: -0.95, max: 0.95, step: 0.05, value: p.rho }, (v) => { p.rho = v; redraw(); });
      const box2 = ui.group(T("classviz.show", "Mostrar"));
      ui.check(box2, "amostra de 300 pontos", st.sample, (v) => { st.sample = v; redraw(); });
      ui.check(box2, "elipses de Mahalanobis 1, 2 e 3", st.ellipses, (v) => { st.ellipses = v; redraw(); });
      const out = ui.readout(ui.group());
      draggable(api, () => [p.mu], (_, mu) => { p.mu = mu; redraw(); });
      setDraw((c) => {
        const c12 = p.rho * p.s1 * p.s2;
        const S = [[p.s1 * p.s1, c12], [c12, p.s2 * p.s2]];
        plot.clear(c.paper);
        plot.heat((x, y) => Math.exp(-0.5 * maha(x, y, p.mu, S)), c.c1);
        plot.grid(c.ink, c.rule, ["x₁", "x₂"]);
        if (st.ellipses) for (const r of [1, 2, 3]) plot.ellipse(p.mu, S, r, c.ink, 1.5, r === 1 ? [] : [4, 4]);
        if (st.sample) {
          const L = chol2(S), ctx = plot.ctx;
          ctx.save();
          ctx.fillStyle = c.p1;
          ctx.globalAlpha = 0.7;
          for (const q of lat) {
            ctx.beginPath();
            ctx.arc(plot.px(p.mu[0] + L[0] * q.z1), plot.py(p.mu[1] + L[1] * q.z1 + L[2] * q.z2), 2.4, 0, 2 * Math.PI);
            ctx.fill();
          }
          ctx.restore();
        }
        plot.handle(p.mu, "μ", c.c1, c.p1);
        out.innerHTML =
          `<div>μ = (${num(p.mu[0])}; ${num(p.mu[1])})</div>` +
          `<div class="classviz-mat-row">Σ = <table class="classviz-mat">` +
          `<tr><td>${num(S[0][0])}</td><td>${num(S[0][1])}</td></tr>` +
          `<tr><td>${num(S[1][0])}</td><td>${num(S[1][1])}</td></tr></table></div>` +
          `<div>det Σ = <b>${num(det2(S), 3)}</b></div>` +
          `<div class="classviz-note">Arraste μ para mover a distribuição.</div>`;
      });
    },

    // ------------------------------------------------------------ qda / lda
    qda(api) { gaussFit(api, "qda"); },
    lda(api) { gaussFit(api, "lda"); },
    logistic(api) { gaussFit(api, "log"); },

    // ------------------------------------------------------------ compare
    compare(api) {
      const { el, ui, plot, redraw, setDraw } = api;
      const st = { key: el.getAttribute("scenario") || "cov_diferentes", n: 100, seed: 1, show: { bayes: true, log: true, lda: true, qda: true } };
      const test = latent(4000, 777);
      const box = ui.group(T("classviz.scenario", "Cenário"));
      const row = ui.buttons(box);
      const scenBtns = Object.keys(SCEN).map((k) => {
        const b = ui.button(row, SCEN_LABEL[k], () => { st.key = k; sync(); redraw(); });
        b.dataset.key = k;
        return b;
      });
      const sync = () => scenBtns.forEach((b) => b.classList.toggle("is-on", b.dataset.key === st.key));
      sync();
      const box2 = ui.group(T("classviz.sample", "Amostra de treino"));
      ui.slider(box2, "n", { min: 30, max: 500, step: 10, value: st.n, fmt: (v) => String(v) }, (v) => { st.n = v; redraw(); });
      ui.button(ui.buttons(box2), "nova amostra", () => { st.seed++; redraw(); });
      const c = api.colors();
      const box3 = ui.group(T("classviz.boundaries", "Fronteiras · erro de teste"));
      const labels = {};
      for (const [k, name, color, dash] of [["bayes", "Bayes", c.ink, true], ["log", "logística", c.log], ["lda", "LDA", c.lda], ["qda", "QDA", c.qda]]) {
        const inp = ui.check(box3, name, st.show[k], (v) => { st.show[k] = v; redraw(); }, { color, dash });
        labels[k] = document.createElement("b");
        labels[k].className = "classviz-err";
        inp.parentElement.append(labels[k]);
      }
      setDraw((c) => {
        const sc = SCEN[st.key];
        const d = realize(sc, latent(st.n, 1000 + st.seed)), T_ = realize(sc, test);
        const scores = { bayes: bayesScore(sc), log: logisticScore(fitLogistic(d.X, d.y)) };
        const lda = fitGaussian(d.X, d.y, true), qda = fitGaussian(d.X, d.y, false);
        if (lda) scores.lda = gaussScore(lda);
        if (qda) scores.qda = gaussScore(qda);
        plot.clear(c.paper);
        plot.shade(scores.bayes, c.c0, c.c1);
        plot.grid(c.ink, c.rule, ["x₁", "x₂"]);
        const styles = { log: { color: c.log, width: 3 }, lda: { color: c.lda, width: 3 }, qda: { color: c.qda, width: 3 }, bayes: { color: c.ink, width: 2.5, dash: [7, 5] } };
        for (const k of ["log", "lda", "qda", "bayes"]) if (st.show[k] && scores[k]) plot.contour(scores[k], styles[k]);
        plot.points(d.X, d.y, [c.p0, c.p1]);
        for (const k in labels) labels[k].textContent = scores[k] ? pct(testError(scores[k], T_)) : "—";
      });
    },
  };

  function gaussFit(api, mode) {
    const { el, ui, plot, redraw, setDraw } = api;
    const methods = (el.getAttribute("methods") || mode).split(",").map((s) => s.trim());
    const p = mode === "qda"
      ? { mu0: [-0.8, 0], mu1: [0.8, 0.3], rho0: 0.75, rho1: -0.45, s1: 1.4, pi1: 0.5, equal: false }
      : { mu0: [-1, -0.5], mu1: [1, 0.7], rho0: 0.4, rho1: 0.4, s1: 1, pi1: 0.5, equal: true };
    const st = { n: 100, seed: 1, bayes: true };
    const test = latent(4000, 4242);
    gaussianControls(api, p, ui.group(T("classviz.truth", "A distribuição verdadeira")));
    const box = ui.group(T("classviz.sample", "Amostra de treino"));
    ui.slider(box, "n", { min: 30, max: 600, step: 10, value: st.n, fmt: (v) => String(v) }, (v) => { st.n = v; redraw(); });
    const row = ui.buttons(box);
    ui.button(row, "nova amostra", () => { st.seed++; redraw(); });
    const c = api.colors();
    ui.check(box, "fronteira de Bayes", st.bayes, (v) => { st.bayes = v; redraw(); }, { color: c.ink, dash: true });
    const out = ui.readout(ui.group(T("classviz.testerr", "Erro de teste")));
    const NAME = { log: "logística", lda: "LDA", qda: "QDA" };
    ui.legend(ui.panel, methods.map((m) => ({
      label: m === "log" ? "logística ajustada" : NAME[m] + " · elipses: covariância estimada",
      color: c[m],
    })));
    setDraw((c) => {
      const sc = twoGaussians(p), bayes = bayesScore(sc);
      const d = realize(sc, latent(st.n, 500 + st.seed)), T_ = realize(sc, test);
      // Gaussianas guardam o ajuste (para as elipses); a logística, só os β.
      const fits = {}, scores = {};
      for (const m of methods) {
        if (m === "log") { scores[m] = logisticScore(fitLogistic(d.X, d.y)); continue; }
        fits[m] = fitGaussian(d.X, d.y, m === "lda");
        if (fits[m]) scores[m] = gaussScore(fits[m]);
      }
      const main = scores[methods[0]];
      plot.clear(c.paper);
      if (main) plot.shade(main, c.c0, c.c1);
      plot.grid(c.ink, c.rule, ["x₁", "x₂"]);
      for (const m of methods) {
        const f = fits[m];
        if (!f) continue;
        for (const k of [0, 1]) plot.ellipse(f.means[k], f.covs[k], 2, c[m], 1.5, [5, 4]);
      }
      if (st.bayes) plot.contour(bayes, { color: c.ink, width: 2.5, dash: [7, 5] });
      for (const m of methods) if (scores[m]) plot.contour(scores[m], { color: c[m], width: 3 });
      plot.points(d.X, d.y, [c.p0, c.p1]);
      plot.handle(p.mu0, "μ₀", c.c0, c.p0);
      plot.handle(p.mu1, "μ₁", c.c1, c.p1);
      let html = `<div>Bayes: <b>${pct(testError(bayes, T_))}</b></div>`;
      for (const m of methods) html += `<div>${NAME[m]}: <b>${scores[m] ? pct(testError(scores[m], T_)) : "—"}</b></div>`;
      out.innerHTML = html;
    });
  }

  function drawSpark(canvas, hist, c) {
    const dpr = window.devicePixelRatio || 1;
    const w = canvas.clientWidth || 200, h = canvas.clientHeight || 70;
    canvas.width = w * dpr; canvas.height = h * dpr;
    const ctx = canvas.getContext("2d");
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    let lo = Infinity, hi = -Infinity;
    for (const v of hist) { if (v < lo) lo = v; if (v > hi) hi = v; }
    if (hi - lo < 1e-9) { hi += 0.01; lo -= 0.01; }
    const pad = 6, top = 20;
    ctx.strokeStyle = c.log;
    ctx.lineWidth = 2;
    ctx.beginPath();
    const N = hist.length, stride = Math.max(1, Math.floor(N / w));
    for (let i = 0; i < N; i += stride) {
      const x = pad + ((w - 2 * pad) * i) / Math.max(1, N - 1);
      const y = h - pad - ((h - pad - top) * (hist[i] - lo)) / (hi - lo);
      i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    }
    ctx.stroke();
    ctx.fillStyle = c.mute;
    ctx.font = `12px ${getComputedStyle(canvas).getPropertyValue("--delta-sans").trim() || "system-ui, sans-serif"}`;
    ctx.textBaseline = "top";
    ctx.fillText("ℓ(β)/n por iteração", pad, 2);
  }

  register();
})();
